function getGroupInfo(hoveredCounty) {
  if (!hoveredCounty) return { counties: new Set(), groupKey: null };
  const groupKey = COUNTY_GROUP[hoveredCounty];
  return { counties: new Set(GROUPS[groupKey]?.counties || []), groupKey };
}
function NameRow({ names, maxWidth, isMobile }) {
  const containerRef = useRef(null);
  const wrapperRef = useRef(null);
  const [rows, setRows] = useState([names]);

  useEffect(() => {
    if (!containerRef.current) return;
    if (names.length <= 1) { setRows([names]); return; }
    const availW = wrapperRef.current
      ? wrapperRef.current.getBoundingClientRect().width
      : (maxWidth || 160);
    containerRef.current.style.width = availW + "px";
    requestAnimationFrame(() => {
      if (!containerRef.current) return;
      const spans = containerRef.current.querySelectorAll("[data-name]");
      const rowMap = new Map();
      spans.forEach((span) => {
        const key = Math.round(span.getBoundingClientRect().top);
        if (!rowMap.has(key)) rowMap.set(key, []);
        rowMap.get(key).push(span.dataset.name);
      });
      const sorted = [...rowMap.entries()]
        .sort((a, b) => a[0] - b[0])
        .map(([, v]) => v);
      setRows(sorted);
    });
  }, [names.join(","), maxWidth]);

  return (
    <div ref={wrapperRef} style={{ width: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: "2px" }}>

      <div
        ref={containerRef}
        aria-hidden="true"
        style={{
          position: "absolute",
          visibility: "hidden",
          pointerEvents: "none",
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          width: "160px",
          gap: "0",
        }}
      >
        {names.map((name) => (
          <span key={name} data-name={name} style={{ fontSize: isMobile ? "15px" : "18px", padding: "0 4px", whiteSpace: "nowrap" }}>
            {name} County
          </span>
        ))}
      </div>

      {rows.map((row, ri) => (
        <div key={ri} style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexWrap: "wrap",
          width: "100%",
          gap: "0",
        }}>
          {row.map((name, i) => (
            <span key={name} style={{ display: "flex", alignItems: "center", flexShrink: 1, minWidth: 0 }}>
              {i > 0 && (
                <span style={{
                  color: "#3f5b74",
                  fontSize: isMobile ? "15px" : "18px",
                  margin: "0 6px",
                  lineHeight: 1,
                  userSelect: "none",
                  flexShrink: 0,
                }}>✦</span>
              )}
              <span style={{
                color: "#c5e5f4",
                fontSize: isMobile ? "15px" : "18px",
                letterSpacing: "0.06em",
                lineHeight: 1.5,
                whiteSpace: "normal",
                overflowWrap: "break-word",
                wordBreak: "break-word",
                textAlign: "center",
              }}>
                {name} County
              </span>
            </span>
          ))}
        </div>
      ))}
    </div>
  );
}

export default function CaliforniaMap() {
  const [hovered, setHovered] = useState(null);
  const [panelText, setPanelText] = useState(GROUP_TEXT.default);
  const [fadeIn, setFadeIn] = useState(true);
  const [clickedEntries, setClickedEntries] = useState([]);
  const [selected, setSelected] = useState(null);

  const winW = useWindowWidth();
  const isMobile = winW < 600;
  const OUTER_PAD = isMobile ? 16 : 48;
  const CARD_PAD = 24;
  const mapW = Math.min(420, winW - OUTER_PAD - CARD_PAD);
  const mapH = Math.round(mapW * (715 / 420));

  const clickedSum = clickedEntries.reduce((s, e) => s + e.number, 0);
  const clickedKeySet = new Set(clickedEntries.map(e => e.key));
  const panelCounty = isMobile ? selected : hovered;
  const isAnySelected = panelCounty !== null;
  const addToTotal = (countyName) => {
    const groupKey = COUNTY_GROUP[countyName];
    const dedupeKey = groupKey || countyName;
    const n = COUNTY_NUMBER[countyName];
    if (n == null) return;
    setClickedEntries(prev => {
      if (prev.some(e => e.key === dedupeKey)) return prev;
      const groupMembers = GROUPS[dedupeKey]?.counties;
      const label = groupMembers && groupMembers.length > 1
        ? groupMembers.sort().join(" · ")
        : countyName;
      return [...prev, { key: dedupeKey, label, number: n }];
    });
  };

  const { counties: groupCounties, groupKey: hoveredGroupKey } = getGroupInfo(panelCounty);
  const isAnyHovered = hovered !== null;
  const isAnyPanelActive = isAnySelected;
  const countyNames = Object.keys(COUNTY_PATHS);
  const highlightedNames = panelCounty ? [...groupCounties].sort() : [];

  const hoveredNumber = panelCounty != null ? COUNTY_NUMBER[panelCounty] : null;
  const displayNumber = hoveredNumber != null ? hoveredNumber.toLocaleString() : "✕";
  const hasNumber = hoveredNumber != null;
  useEffect(() => {
    const newText = hoveredGroupKey
      ? (GROUP_TEXT[hoveredGroupKey] ?? GROUP_TEXT.default)
      : GROUP_TEXT.default;
    setFadeIn(false);
    const t = setTimeout(() => {
      setPanelText(newText);
      setFadeIn(true);
    }, 180);
    return () => clearTimeout(t);
  }, [hoveredGroupKey]);

  return (
    <div style={{
      minHeight: "100vh",
      background: "#3f5b74",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "Georgia, \'Times New Roman\', serif",
      padding: isMobile ? "12px 8px" : "24px",
      gap: "0",
      boxSizing: "border-box",
      width: "100%",
      overflowX: "hidden",
    }}>

      {/* Title */}
      <div style={{ textAlign: "center", marginBottom: "16px" }}>
        <h1 style={{
          color: "#c5e5f4",
          fontSize: isMobile ? "18px" : "26px",
          fontWeight: 400,
          letterSpacing: isMobile ? "0.15em" : "0.25em",
          textTransform: "uppercase",
          margin: 0,
          textShadow: "0 2px 20px rgba(200,180,130,0.2)",
        }}>California MSVI Listings</h1>
        <p style={{
          color: "#7a9ab0",
          fontSize: isMobile ? "9px" : "17px",
          letterSpacing: isMobile ? "0.2em" : "0.4em",
          textTransform: "uppercase",
          margin: "5px 0 0",
        }}>58 Counties · Hover to Select</p>
      </div>

      {/* Map + Panel row */}
      <div style={{
        display: "flex",
        flexDirection: isMobile ? "column" : "row",
        alignItems: isMobile ? "center" : "flex-start",
        gap: isMobile ? "12px" : "20px",
        flexWrap: "wrap",
        justifyContent: "center",
        width: "100%",
        maxWidth: "960px",
      }}>

        {/* Map card */}
        <div style={{
          background: "rgba(63,91,116,0.12)",
          borderRadius: "12px",
          border: "1px solid rgba(197,229,244,0.14)",
          padding: "12px",
          boxShadow: "0 20px 60px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.05)",
          flexShrink: 0,
        }}>
          <svg
            viewBox="0 0 93.572 159.56"
            width={mapW}
            height={mapH}
            style={{ display: "block" }}
          >
            <defs>
              <filter id="drop" x="-5%" y="-5%" width="110%" height="110%">
                <feDropShadow dx="0" dy="0.12" stdDeviation="0.22"
                  floodColor="#000" floodOpacity="0.4" />
              </filter>
              <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
                <feGaussianBlur stdDeviation="0.45" result="blur"/>
                <feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>
              </filter>
              <pattern id="hatch" patternUnits="userSpaceOnUse"
                width="1.4" height="1.4" patternTransform="rotate(45)">
                <rect width="1.4" height="1.4" fill="#efba18"/>
                <line x1="0" y1="0" x2="0" y2="1.4" stroke="#705800" strokeWidth="0.55"/>
              </pattern>
              <pattern id="hatch-hover" patternUnits="userSpaceOnUse"
                width="1.4" height="1.4" patternTransform="rotate(45)">
                <rect width="1.4" height="1.4" fill="#c99a10"/>
                <line x1="0" y1="0" x2="0" y2="1.4" stroke="#503800" strokeWidth="0.55"/>
              </pattern>
            </defs>

            {countyNames.map((name) => {
              const group   = COUNTY_GROUP[name];
              const inGroup = groupCounties.has(name);
              const gData   = GROUPS[group];
              const isHatch = group === "gold_hatch";
              const fill    = isHatch
                ? (inGroup ? "url(#hatch-hover)" : "url(#hatch)")
                : (inGroup ? gData.hover : gData.color);
              return (
                <path
                  key={name}
                  d={COUNTY_PATHS[name]}
                  fill={fill}
                  fillOpacity={(isAnyHovered || (isMobile && isAnyPanelActive)) && !inGroup ? 0.32 : 0.88}
                  stroke="#111"
                  strokeWidth={inGroup ? "0.22" : "0.09"}
                  strokeOpacity={0.9}
                  filter={inGroup ? "url(#glow)" : "url(#drop)"}
                  style={{ cursor: "pointer", transition: "fill-opacity 0.18s, stroke-width 0.15s" }}
                  onMouseEnter={() => { if (!isMobile) setHovered(name); }}
                  onMouseLeave={() => { if (!isMobile) setHovered(null); }}
                  onClick={() => {
                    if (isMobile) {
                      setSelected(name);
                    } else {
                      addToTotal(name);
                    }
                  }}
                />
              );
            })}

            {countyNames.map((name) => {
              const [cx, cy] = CENTROIDS[name];
              const inGroup  = groupCounties.has(name);
              return (
                <text
                  key={`lbl-${name}`}
                  x={cx} y={cy}
                  textAnchor="middle"
                  dominantBaseline="middle"
                  fontSize={inGroup ? "2.1" : "1.6"}
                  fontWeight={inGroup ? "700" : "500"}
                  fill={inGroup
                    ? "#fff"
                    : (isAnyHovered ? "rgba(197,229,244,0.35)" : "rgba(197,229,244,0.92)")}
                  stroke={inGroup ? "rgba(0,0,0,0.7)" : "rgba(0,0,0,0.65)"}
                  strokeWidth={inGroup ? "0.6" : "0.45"}
                  paintOrder="stroke"
                  pointerEvents="none"
                  style={{ transition: "font-size 0.15s, fill 0.15s" }}
                >{name}</text>
              );
            })}
          </svg>
        </div>

        {/* Info panel */}
        <div style={{
          width: isMobile ? Math.min(mapW + CARD_PAD, winW - OUTER_PAD) : "320px",
          alignSelf: isMobile ? "center" : "stretch",
          boxSizing: "border-box",
          background: "rgba(63,91,116,0.15)",
          borderRadius: "12px",
          border: "1px solid rgba(197,229,244,0.14)",
          padding: "20px",
          boxShadow: "0 20px 60px rgba(0,0,0,0.4)",
          display: "flex",
          flexDirection: "column",
          minHeight: isMobile ? "auto" : "500px",
        }}>

          {/* Top 1/3 — Region Info */}
          <div style={{
            flex: "0 0 33.333%",
            borderBottom: isAnyPanelActive ? "1px solid rgba(197,229,244,0.14)" : "none",
            paddingBottom: "14px",
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
          }}>
            <p style={{
              color: "#7a9ab0",
              fontSize: isMobile ? "9px" : "17px",
              letterSpacing: "0.35em",
              textTransform: "uppercase",
              margin: "0 0 10px 0",
              lineHeight: 1,
              flexShrink: 0,
            }}>Region Info</p>

            {isAnyPanelActive ? (
              <div style={{
                display: "flex",
                alignItems: "flex-start",
                width: "100%",
                flex: 1,
                minHeight: 0,
              }}>
                {/* County names — 2/3 width, wrapping */}
                <div style={{
                  flex: "0 0 66.666%",
                  minWidth: 0,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  paddingRight: "8px",
                  overflow: "hidden",
                  alignSelf: "center",
                }}>
                  <NameRow names={highlightedNames} maxWidth={isMobile ? Math.round((mapW - 16) * 0.667) : 155} isMobile={isMobile} />
                </div>

                {/* Divider */}
                <div style={{
                  width: "1px",
                  alignSelf: "stretch",
                  background: "rgba(197,229,244,0.15)",
                  flexShrink: 0,
                }}/>

                {/* Listings — 1/3 width */}
                <div style={{
                  flex: "0 0 33.333%",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  paddingLeft: "8px",
                  gap: "4px",
                  alignSelf: "center",
                }}>
                  <span style={{
                    color: "#7a9ab0",
                    fontSize: isMobile ? "8px" : "11px",
                    letterSpacing: "0.25em",
                    textTransform: "uppercase",
                    lineHeight: 1,
                    textAlign: "center",
                  }}>Listings</span>
                  <span style={{
                    color: hasNumber ? "#d8c7ac" : "#c63947",
                    fontSize: isMobile ? "20px" : "23px",
                    fontWeight: "600",
                    letterSpacing: "0.02em",
                    lineHeight: 1.1,
                  }}>
                    {displayNumber}
                  </span>
                  {isMobile && hasNumber && (() => {
                    const gk = COUNTY_GROUP[panelCounty];
                    const dk = gk || panelCounty;
                    const alreadyAdded = clickedEntries.some(e => e.key === dk);
                    return (
                      <button
                        onClick={() => addToTotal(panelCounty)}
                        disabled={alreadyAdded}
                        style={{
                          marginTop: "4px",
                          background: alreadyAdded ? "rgba(197,229,244,0.04)" : "rgba(197,229,244,0.12)",
                          border: "1px solid rgba(197,229,244,0.2)",
                          borderRadius: "6px",
                          color: alreadyAdded ? "#3f5b74" : "#c5e5f4",
                          fontSize: isMobile ? "9px" : "17px",
                          letterSpacing: "0.1em",
                          textTransform: "uppercase",
                          padding: "5px 6px",
                          cursor: alreadyAdded ? "default" : "pointer",
                          width: "100%",
                          lineHeight: 1.2,
                          textAlign: "center",
                        }}
                      >
                        {alreadyAdded ? "Added" : "+ Add"}
                      </button>
                    );
                  })()}
                </div>
              </div>
            ) : (
              <div style={{
                flex: 1,
                display: "flex",
                alignItems: "center",
              }}>
                <p style={{
                  color: "#3f5b74",
                  fontSize: isMobile ? "13px" : "16px",
                  margin: 0,
                  lineHeight: 1.5,
                  fontStyle: "italic",
                }}>Hover a county to view details</p>
              </div>
            )}
          </div>

          {/* Bottom 2/3 — Data fields, only when hovered */}
          {isAnyPanelActive && (() => {
            const groupKey = COUNTY_GROUP[hovered];
            const fields = DATA_FIELDS[groupKey] || DATA_FIELDS[hovered] || ["Corporation Names"];
            return (
              <div style={{
                flex: "1 1 66.666%",
                paddingTop: "16px",
                display: "flex",
                flexDirection: "column",
                gap: "0",
              }}>
                <p style={{
                  color: "#7a9ab0",
                  fontSize: isMobile ? "9px" : "17px",
                  letterSpacing: "0.35em",
                  textTransform: "uppercase",
                  margin: "0 0 12px 0",
                  lineHeight: 1,
                }}>Data Includes</p>
                {fields.map((label) => (
                  <div key={label} style={{
                    display: "flex",
                    alignItems: "flex-start",
                    gap: "10px",
                    padding: "10px 0",
                    borderBottom: "1px solid rgba(197,229,244,0.07)",
                  }}>
                    <span style={{
                      width: "5px",
                      height: "5px",
                      borderRadius: "50%",
                      background: "#3f5b74",
                      flexShrink: 0,
                      marginTop: "5px",
                    }}/>
                    <div>
                      <p style={{
                        color: "#c5e5f4",
                        fontSize: isMobile ? "13px" : "16px",
                        fontWeight: "600",
                        margin: "0 0 2px 0",
                        lineHeight: 1.3,
                        letterSpacing: "0.03em",
                      }}>{label}</p>
                      <p style={{
                        color: "#7a9ab0",
                        fontSize: isMobile ? "11px" : "14px",
                        margin: 0,
                        lineHeight: 1.4,
                      }}>{FIELD_DESC[label]}</p>
                    </div>
                  </div>
                ))}
              </div>
            );
          })()}

        </div>

        {/* Running total panel */}
        {clickedEntries.length > 0 && (
          <div style={{
            width: isMobile ? Math.min(mapW + CARD_PAD, winW - OUTER_PAD) : "400px",
            alignSelf: isMobile ? "center" : "flex-start",
            boxSizing: "border-box",
            background: "rgba(63,91,116,0.15)",
            borderRadius: "12px",
            border: "1px solid rgba(197,229,244,0.14)",
            padding: "16px 14px",
            boxShadow: "0 20px 60px rgba(0,0,0,0.4)",
            display: "flex",
            flexDirection: "column",
            gap: "0",
          }}>
            {/* Header */}
            <div style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "flex-start",
              marginBottom: "10px",
            }}>
              <div>
                <p style={{
                  color: "#7a9ab0",
                  fontSize: isMobile ? "8px" : "16px",
                  letterSpacing: "0.3em",
                  textTransform: "uppercase",
                  margin: "0 0 4px 0",
                  lineHeight: 1,
                }}>Total Listings</p>
                <p style={{
                  color: "#d8c7ac",
                  fontSize: isMobile ? "26px" : "34px",
                  fontWeight: "700",
                  margin: 0,
                  lineHeight: 1,
                  letterSpacing: "0.02em",
                }}>{clickedSum.toLocaleString()}</p>
              </div>
              <button
                onClick={() => setClickedEntries([])}
                style={{
                  background: "rgba(197,229,244,0.07)",
                  border: "1px solid rgba(197,229,244,0.15)",
                  borderRadius: "6px",
                  color: "#7a9ab0",
                  fontSize: isMobile ? "9px" : "17px",
                  letterSpacing: "0.08em",
                  padding: "4px 8px",
                  cursor: "pointer",
                  flexShrink: 0,
                  marginLeft: "8px",
                }}
              >Reset</button>
            </div>

            <p style={{
              color: "#506878",
              fontSize: isMobile ? "9px" : "17px",
              letterSpacing: "0.2em",
              textTransform: "uppercase",
              margin: "0 0 8px 0",
              lineHeight: 1,
            }}>{clickedEntries.length} {clickedEntries.length !== 1 ? "counties/groups" : "county/group"}</p>

            {/* Divider */}
            <div style={{ height: "1px", background: "rgba(197,229,244,0.1)", marginBottom: "10px" }}/>

            {/* Entry list */}
            <div style={{
              display: "flex",
              flexDirection: "column",
              gap: "0",
              maxHeight: "360px",
              overflowY: "auto",
            }}>
              {clickedEntries.map((entry, i) => (
                <div key={entry.key} style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "flex-start",
                  padding: "7px 0",
                  borderBottom: i < clickedEntries.length - 1
                    ? "1px solid rgba(197,229,244,0.07)"
                    : "none",
                  gap: "8px",
                }}>
                  <p style={{
                    color: "#c5e5f4",
                    fontSize: isMobile ? "11px" : "19px",
                    margin: 0,
                    lineHeight: 1.35,
                    flex: 1,
                    letterSpacing: "0.02em",
                  }}>{entry.label}</p>
                  <p style={{
                    color: "#d8c7ac",
                    fontSize: isMobile ? "12px" : "20px",
                    fontWeight: "600",
                    margin: 0,
                    lineHeight: 1.35,
                    flexShrink: 0,
                    letterSpacing: "0.02em",
                  }}>{entry.number.toLocaleString()}</p>
                </div>
              ))}
            </div>
          </div>
        )}

      </div>

    </div>
  );
}